const result={batchId:batch.batchId||"UNKNOWN",status:"EXECUTED",executed:true,pipeline,materialization,modules:batch.modules||[],timestamp:Date.now()};
trace.push(AfriNucChainTrace.create("EXECUTION_COMPLETE",result));
