        const result = await RewriteImportHandler.execute(operation);

        results.push({
          type:operation.type,
          status:result.patched ? "EXECUTED" : "FAILED",
          result
        });

      }

      if(operation.type === "MOVE_FILE"){

        results.push({
          type:operation.type,
          status:"READY",
          target:operation.target
        });

      }

      if(operation.type === "REMOVE_FILE"){

        results.push({
          type:operation.type,
          status:"READY",
          target:operation.target
        });

      }

    }

    return {
      status:"OPERATIONS_READY",
      validation,
      operations:results,
      timestamp:Date.now()
    };

  }

};

